  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
export class SlotPool {
  #leases = new Set();
  constructor(capacity = 1) { this.capacity = capacity; this.started = 0; this.released = 0; }
